import SwiftUI

enum NyanCatImage {
    static let base64 = ""
    
    static var image: Image {
        let data = Data(base64Encoded: base64)!
        #if os(macOS)
        let nsImage = NSImage(data: data)!
        return Image(nsImage: nsImage)
        #else
        let uiImage = UIImage(data: data)!
        return Image(uiImage: uiImage)
        #endif
    }
}
